def should_defer_quiet_hours(pref: dict, priority: str, local_hour: int) -> bool:
    if priority == 'P0':
        return False
    start, end = pref.get('quiet_start', 22), pref.get('quiet_end', 8)
    if start > end:
        return local_hour >= start or local_hour < end
    return start <= local_hour < end

from html import escape

def render_template(tmpl: str, variables: dict, max_len: int = 0) -> str:
    safe_vars = {k: escape(str(v)) for k, v in variables.items()}
    rendered = tmpl.format(**safe_vars)
    return rendered[:max_len] if max_len > 0 else rendered

def fanout_segment_slices(db, producer, campaign_id: str, batch_size: int = 1000):
    last_id = 0
    while True:
        users = db.fetch_segment_batch(campaign_id, after_id=last_id, limit=batch_size)
        if not users:
            break
        producer.send('notif.p2.bulk', {'campaign_id': campaign_id, 'user_ids': [u.id for u in users]})
        last_id = users[-1].id

def dispatch_with_fallback(primary_fn, backup_fn, payload: dict) -> str:
    try:
        return primary_fn(payload)
    except ProviderUnavailableError:
        return backup_fn(payload)

import hmac, hashlib, ipaddress, socket

def verify_safe_public_host(hostname: str) -> str:
    ip = socket.gethostbyname(hostname)
    addr = ipaddress.ip_address(ip)
    if addr.is_private or addr.is_loopback or addr.is_link_local:
        raise SecurityError(f'Blocked SSRF target IP: {ip}')
    return ip

def sign_webhook(secret: bytes, body: bytes) -> str:
    return 'sha256=' + hmac.new(secret, body, hashlib.sha256).hexdigest()

